            'sections' => [
                ['id' => 'modalites', 'title' => 'Les modalités en bref', 'paragraphs' => ['Les règles ci-dessous concernent les achats à distance par des consommateurs, sous réserve des exceptions légales applicables à certains biens. L’adresse de retour est confirmée ; l’organisation du transport gratuit doit être convenue avec HOMYA.'], 'items' => ['Délai de rétractation : 14 jours calendaires après réception pour notifier votre décision ; renvoi dans les 14 jours suivant cette notification.', 'Remboursement : au plus tard 14 jours après notification, sous réserve du report légal expliqué ci-dessous. Le crédit bancaire dépend du prestataire.', 'Livraison aller gratuite en France, Belgique et Allemagne ; HOMYA prend en charge les retours demandés dans les 14 jours après réception.', 'Notification et retour : HOMYA, à l’adresse de retour publiée ci-dessous. Une déclaration sans ambiguïté suffit pour notifier la rétractation.', 'Un défaut relève des garanties légales, distinctes du changement d’avis. Aucune exclusion générale des produits soldés, ouverts ou volumineux.']],
                ['id' => 'delai', 'title' => '14 jours pour notifier une rétractation', 'paragraphs' => ['Vous disposez, pour les biens concernés par le droit légal de rétractation, de 14 jours calendaires à compter de leur réception par vous-même ou par un tiers désigné autre que le transporteur. Pour plusieurs biens livrés séparément ou un bien livré en plusieurs lots, le délai court à compter de la réception du dernier bien ou lot. Le jour de réception ne compte pas dans le délai. En France, si le dernier jour tombe un samedi, un dimanche ou un jour férié ou chômé, il est reporté au premier jour ouvrable suivant.', 'Vous n’avez pas à justifier votre décision. Adressez une déclaration sans ambiguïté à HOMYA au siège indiqué dans les mentions légales. Les coordonnées e-mail figurent sur la page Contact. Une promotion ne supprime pas ce droit.']],
                ['id' => 'retour', 'title' => 'Renvoi et remboursement', 'paragraphs' => ['Renvoyez le bien sans retard excessif et au plus tard dans les 14 jours suivant la notification de votre rétractation, sauf si HOMYA propose de le récupérer. L’adresse ci-dessous reçoit aussi les palettes, meubles et appareils volumineux.', 'Le remboursement porte sur les sommes payées pour le bien et les frais éventuels de livraison standard. Le supplément lié à un mode de livraison plus coûteux choisi par le client n’est pas remboursé au titre de cette règle.', 'Le remboursement est effectué au plus tard dans les 14 jours à compter de la notification de votre décision. Dans les cas prévus par la loi, HOMYA peut attendre la récupération du bien ou la preuve de son expédition, la première de ces dates étant retenue. Ce report ne s’applique pas si HOMYA propose de récupérer le bien.', 'Le même moyen de paiement est utilisé, sauf accord exprès pour un autre moyen sans frais supplémentaires. Le délai de crédit du prestataire bancaire doit être précisé séparément ; il ne remplace pas le délai légal applicable.', 'HOMYA prend en charge les frais de retour pour une rétractation notifiée dans les 14 jours après réception. Cette gratuité est un engagement commercial HOMYA. Convenez du transport avec HOMYA : étiquette prépayée pour un colis adapté ou enlèvement pour un bien volumineux, selon la solution organisée. Si vous avancez des frais directs de renvoi, conservez le justificatif pour leur prise en charge ; aucune autorisation préalable ne conditionne votre droit de rétractation.'], 'return_details' => true],
                ['id' => 'emballage', 'title' => 'Préparer le colis ou l’enlèvement', 'paragraphs' => ['Protégez le produit pour le transport et joignez ses accessoires ainsi que sa référence de commande, si disponible. L’emballage d’origine est recommandé lorsqu’il existe, mais son absence ou l’ouverture du colis ne supprime pas automatiquement le droit de rétractation.', 'Une éventuelle dépréciation doit résulter de manipulations dépassant celles nécessaires pour établir la nature, les caractéristiques et le bon fonctionnement du bien, sous les conditions légales d’information. Aucun frais forfaitaire de remise en stock ni pénalité de retour n’est appliqué.']],
                ['id' => 'exceptions', 'title' => 'Exceptions et produits défectueux', 'paragraphs' => ['Les exceptions légales doivent être examinées produit par produit et communiquées avant l’achat lorsqu’elles s’appliquent, notamment pour un bien réellement confectionné sur mesure. Aucune exclusion générale des produits ouverts, soldés ou volumineux n’est appliquée ici.', 'En cas de défaut ou de non-conformité, indiquez votre commande et le problème rencontré. Ce recours relève des garanties légales et n’est pas limité aux 14 jours de rétractation. La mise en conformité sous la garantie légale de conformité est sans frais pour le consommateur, y compris les frais nécessaires de transport ; ce parcours reste distinct d’un retour pour changement d’avis.']],
                ['id' => 'france', 'title' => 'France · rétractation en ligne', 'paragraphs' => ['L’article L221-21 du Code de la consommation, en vigueur depuis le 19 juin 2026, prévoit une fonctionnalité gratuite de rétractation pour les contrats conclus à distance au moyen d’une interface en ligne. Elle devra être disponible pendant le délai de rétractation et accompagnée d’un accusé de réception.']],
                ['id' => 'belgique', 'title' => 'Belgique · rétractation en ligne', 'paragraphs' => ['Le SPF Économie indique que la fonctionnalité de rétractation en ligne est obligatoire depuis le 14 août 2026. Elle doit être facile à trouver et à utiliser, disponible pendant le délai, et suivie d’une confirmation.']],
                ['id' => 'allemagne', 'title' => 'Allemagne · Widerruf', 'paragraphs' => ['Le BGB § 356a prévoit une fonction de rétractation accessible pendant le délai, puis une confirmation explicite et un accusé conservable indiquant la déclaration, la date et l’heure. L’information de rétractation et le formulaire type allemands devront être adaptés au vendeur.']],
                ['id' => 'procedure', 'title' => 'Comment demander un retour', 'paragraphs' => ['Notifiez d’abord votre décision, puis organisez le transport gratuit. L’adresse de réception des retours figure ci-dessus. Les coordonnées électroniques sont accessibles sur la page Contact ; le courrier permet également de notifier une décision.'], 'items' => ['Pour notifier votre décision par courrier, adressez votre déclaration sans ambiguïté à HOMYA au siège publié dans les mentions légales. Vous pouvez utiliser le modèle de déclaration ci-dessous ; son utilisation n’est pas obligatoire.', 'Indiquez la nature du bien et les contraintes d’accès utiles au transport. HOMYA doit organiser et prendre en charge une solution adaptée : colis ou enlèvement pour les biens volumineux. Les horaires et le rendez-vous d’enlèvement restent à convenir ; l’attente d’une instruction logistique ne doit pas vous faire perdre vos droits.', 'Renvoyez le bien dans le délai applicable et gardez la preuve d’envoi. Le droit de rétractation ne dépend pas d’une autorisation préalable du vendeur.', 'Le remboursement suit les conditions ci-dessus. Identifiez votre commande pour permettre le rapprochement ; ne communiquez pas de mot de passe ou de données complètes de carte.']],
                ['id' => 'declaration', 'title' => 'Modèle de déclaration par courrier', 'paragraphs' => ['À l’attention de HOMYA, au siège publié dans les mentions légales. Je vous notifie ma rétractation du contrat portant sur le bien suivant : [produit / référence]. Commandé le [date] et reçu le [date]. Référence de commande : [référence]. Nom et adresse du consommateur : [nom / adresse]. Date : [date]. Signature du consommateur pour une déclaration papier.', 'L’adresse indiquée ci-dessus reçoit votre notification et les produits retournés. Pour les biens volumineux, convenez du transport avec HOMYA ; la notification de rétractation n’exige pas l’accord préalable du vendeur.']],
                ['id' => 'preparation', 'title' => 'Modalités HOMYA à compléter', 'items' => ['Transporteur, étiquettes prépayées, modalités et rendez-vous d’enlèvement gratuit à organiser, notamment pour les biens volumineux.', 'Fonction en ligne avec accusé de réception.', 'Traitement effectif des remboursements à vérifier avant publication commerciale.'], 'paragraphs' => ['La fonction de rétractation en ligne et son accusé de réception restent à mettre en place. Le courrier au siège permet de notifier une décision ; cette page ne transmet pas de demande.']],
